BEGIN;

CREATE TABLE IF NOT EXISTS public.insurance_data (
  id integer PRIMARY KEY,
  policy_no text NOT NULL,
  policy_issue_date text,
  insured_name text NOT NULL,
  policy_start text,
  policy_expiry text,
  type text NOT NULL,
  charges text NOT NULL,
  car_vin text NOT NULL,
  car_type text NOT NULL,
  car_make text NOT NULL,
  car_year text NOT NULL,
  car_plate text NOT NULL,
  emirates text NOT NULL,
  phone text NOT NULL,
  insurance_name text NOT NULL,
  plan text NOT NULL,
  status text NOT NULL DEFAULT 'ACTIVE',
  pay_status text NOT NULL DEFAULT 'Unpaid',
  certificate_no text NOT NULL,
  branch text NOT NULL,
  data_month text NOT NULL,
  data_year integer NOT NULL,
  date_created text NOT NULL DEFAULT CURRENT_TIMESTAMP::text,
  company_id uuid NOT NULL DEFAULT 'd32af79a-fdde-4052-a8f1-6bc69ba3544e'::uuid
);

ALTER TABLE public.insurance_data
  ADD COLUMN IF NOT EXISTS company_id uuid NOT NULL DEFAULT 'd32af79a-fdde-4052-a8f1-6bc69ba3544e'::uuid;
UPDATE public.insurance_data
SET company_id = 'd32af79a-fdde-4052-a8f1-6bc69ba3544e'::uuid
WHERE company_id IS NULL;
ALTER TABLE public.insurance_data
  ALTER COLUMN company_id SET DEFAULT 'd32af79a-fdde-4052-a8f1-6bc69ba3544e'::uuid;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'insurance_data_company_id_fkey'
  ) THEN
    ALTER TABLE public.insurance_data
      ADD CONSTRAINT insurance_data_company_id_fkey
      FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE CASCADE;
  END IF;
END
$$;

CREATE INDEX IF NOT EXISTS insurance_data_car_vin_idx ON public.insurance_data (car_vin);
CREATE INDEX IF NOT EXISTS insurance_data_company_id_idx ON public.insurance_data (company_id);
